#include <furi.h>
#include <gui/gui.h>
#include <gui/view_dispatcher.h>
#include <gui/modules/widget.h>
#include <gui/modules/number_input.h>
#include <gui/modules/text_box.h>

/* generated by fbt from .png files in images folder */
#include <prime_factors_icons.h>

/*
 * Prime factorization by plain trial division.
 *
 * NumberInput hands us an int32_t, so the supported range is 0..INT32_MAX.
 * A number below 2^31 has at most 30 prime factors (2^30), so 31 slots is
 * always enough.
 */
#define MAX_FACTORS 31

typedef enum {
    ViewWelcome,
    ViewInput,
    ViewResult,
} ViewId;

typedef struct {
    ViewDispatcher* dispatcher;
    Widget* welcome;
    NumberInput* input;
    TextBox* result;
    FuriString* text; /* text shown on the result screen */
} App;

/* Store the prime factors of n (n >= 2) in out[], smallest first. Returns how many. */
static size_t prime_factors(uint32_t n, uint32_t* out, size_t max) {
    size_t count = 0;

    /* "d * d <= n", written as a division so it can never overflow. */
    for(uint32_t d = 2; d <= n / d; d++) {
        /* Record d for as long as it divides what is left. */
        while(n % d == 0 && count < max) {
            out[count++] = d;
            n /= d;
        }
    }

    /* Whatever is left over (if > 1) has no divisor <= its square root: it is prime. */
    if(n > 1 && count < max) out[count++] = n;

    return count;
}

/* Build the text for the result screen. */
static void build_result_text(FuriString* text, uint32_t n) {
    if(n == 0) {
        furi_string_set(text, "0 is not valid.\nEnter a positive integer.");
    } else if(n == 1) {
        furi_string_set(text, "1 has no prime factors");
    } else {
        uint32_t factors[MAX_FACTORS];
        size_t count = prime_factors(n, factors, MAX_FACTORS);

        /* e.g. "360 =\n2 x 2 x 2 x 3 x 3 x 5"; the text box wraps long lines. */
        furi_string_printf(text, "%lu =\n", n);
        for(size_t i = 0; i < count; i++) {
            if(i > 0) furi_string_cat(text, " x ");
            furi_string_cat_printf(text, "%lu", factors[i]);
        }
    }
}

/* OK on the welcome screen -> number entry. */
static void welcome_button_callback(GuiButtonType button, InputType type, void* context) {
    UNUSED(button);
    App* app = context;
    if(type == InputTypeShort) {
        view_dispatcher_switch_to_view(app->dispatcher, ViewInput);
    }
}

/* The user confirmed a number: factorize it and show the result. */
static void number_input_callback(void* context, int32_t number) {
    App* app = context;
    build_result_text(app->text, (uint32_t)number);
    text_box_set_text(app->result, furi_string_get_cstr(app->text));
    view_dispatcher_switch_to_view(app->dispatcher, ViewResult);
}

/* Back button: result -> number entry -> welcome -> exit. */
static uint32_t back_to_input(void* context) {
    UNUSED(context);
    return ViewInput;
}

static uint32_t back_to_welcome(void* context) {
    UNUSED(context);
    return ViewWelcome;
}

/* Back on the welcome screen has nowhere to go: returning false stops the app. */
static bool navigation_callback(void* context) {
    UNUSED(context);
    return false;
}

int32_t flipper_prime_factors_app(void* p) {
    UNUSED(p);

    App app = {
        .dispatcher = view_dispatcher_alloc(),
        .welcome = widget_alloc(),
        .input = number_input_alloc(),
        .result = text_box_alloc(),
        .text = furi_string_alloc(),
    };

    /* Welcome screen: title and prompt. */
    widget_add_string_element(
        app.welcome, 64, 14, AlignCenter, AlignCenter, FontPrimary, "Prime Factorization");
    widget_add_string_element(
        app.welcome, 64, 32, AlignCenter, AlignCenter, FontSecondary, "Enter an integer");
    widget_add_string_element(
        app.welcome, 64, 44, AlignCenter, AlignCenter, FontSecondary, "1 to 2147483647");
    widget_add_button_element(
        app.welcome, GuiButtonTypeCenter, "Enter", welcome_button_callback, &app);

    /*
     * Number entry: allow 0..INT32_MAX (negatives cannot be typed).
     * Start at 1, not 0: NumberInput never lets the user delete a leading "0",
     * but it does let them delete a positive number down to an empty field.
     */
    number_input_set_header_text(app.input, "Enter integer");
    number_input_set_result_callback(app.input, number_input_callback, &app, 1, 0, INT32_MAX);

    text_box_set_font(app.result, TextBoxFontText);

    /* Back input */
    view_set_previous_callback(number_input_get_view(app.input), back_to_welcome);
    view_set_previous_callback(text_box_get_view(app.result), back_to_input);

    view_dispatcher_set_event_callback_context(app.dispatcher, &app);
    view_dispatcher_set_navigation_event_callback(app.dispatcher, navigation_callback);
    view_dispatcher_add_view(app.dispatcher, ViewWelcome, widget_get_view(app.welcome));
    view_dispatcher_add_view(app.dispatcher, ViewInput, number_input_get_view(app.input));
    view_dispatcher_add_view(app.dispatcher, ViewResult, text_box_get_view(app.result));

    Gui* gui = furi_record_open(RECORD_GUI);
    view_dispatcher_attach_to_gui(app.dispatcher, gui, ViewDispatcherTypeFullscreen);
    view_dispatcher_switch_to_view(app.dispatcher, ViewWelcome);
    view_dispatcher_run(app.dispatcher); /* blocks until the user backs out */

    /* Cleanup. */
    view_dispatcher_remove_view(app.dispatcher, ViewWelcome);
    view_dispatcher_remove_view(app.dispatcher, ViewInput);
    view_dispatcher_remove_view(app.dispatcher, ViewResult);
    view_dispatcher_free(app.dispatcher);
    widget_free(app.welcome);
    number_input_free(app.input);
    text_box_free(app.result);
    furi_string_free(app.text);
    furi_record_close(RECORD_GUI);

    return 0;
}
